mapper.select:
SELECT r.*, a.title AS activity_title, u.real_name AS customer_name, u.phone AS customer_phone
FROM activity_registration r
LEFT JOIN activity a ON r.activity_id = a.id
LEFT JOIN sys_user u ON r.user_id = u.id


        AND r.activity_id = #{activityId}


        AND a.title LIKE CONCAT('%', #{activityTitle}, '%')


        AND r.user_id = #{userId}


        AND r.audit_status = #{auditStatus}


        AND r.created_at >= #{regStartTime}


        AND r.created_at <= #{regEndTime}


ORDER BY r.created_at DESC

